#include "stdlib/blas/base/dspmv.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/xerbla.h"
#include "stdlib/blas/base/dscal.h"
#include "stdlib/blas/ext/base/dfill.h"

/**
* Performs the matrix-vector operation `Y = alpha*A*X + beta*Y` where `alpha` and `beta` are scalars, `X` and `Y` are `N` element vectors, and `A` is an `N` by `N` symmetric matrix supplied in packed form.
*
* @param order         storage layout
* @param uplo          specifies whether the upper or lower triangular part of the symmetric matrix `A` is supplied
* @param N             number of elements along each dimension of `A`
* @param alpha         scalar constant
* @param AP            packed form of a symmetric matrix `A`
* @param offsetAP      starting `AP` index
* @param X             first input array
* @param strideX       `X` stride length
* @param offsetX       starting `X` index
* @param beta          scalar constant
* @param Y             second input array
* @param strideY       `Y` stride length
* @param offsetY       starting `Y` index
* @returns				  output value
*/
void API_SUFFIX(c_dspmv_ndarray)( const CBLAS_LAYOUT order, const CBLAS_UPLO uplo, const CBLAS_INT N, const double alpha, const double *AP, const CBLAS_INT offsetAP, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const double beta, double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	CBLAS_INT ix;
	CBLAS_INT iy;
	CBLAS_INT jx;
	CBLAS_INT jy;
	CBLAS_INT kk;
	CBLAS_INT kx;
	CBLAS_INT ky;
	CBLAS_INT j;
	CBLAS_INT k;
	double temp1;
	double temp2;

	// Note on variable naming convention: da#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	// Perform input argument validation...
	if ( order != CblasColMajor && order != CblasRowMajor ) {
		c_xerbla( 1, "c_dspmv_ndarray", "Error: invalid argument. First argument must be a valid storage order. Value: `%d`.", order );
		return;
	}
	if ( uplo != CblasUpper && uplo != CblasLower ) {
		c_xerbla( 2, "c_dspmv_ndarray", "Error: invalid argument. Second argument must be a either upper or lower. Value: `%d`.", uplo );
		return;
	}
	if ( N < 0 ) {
		c_xerbla( 3, "c_dspmv_ndarray", "Error: invalid argument. Third argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	if ( strideX == 0 ) {
		c_xerbla( 8, "c_dspmv_ndarray", "Error: invalid argument. Eighth argument must be a nonzero. Value: `%d`.", strideX );
		return;
	}
	if ( strideY == 0 ) {
		c_xerbla( 12, "c_dspmv_ndarray", "Error: invalid argument. Twelfth argument must be a nonzero. Value: `%d`.", strideY );
		return;
	}
	// Check whether we can avoid computation altogether...
	if ( N == 0 || ( alpha == 0.0 && beta == 1.0 ) ) {
		return;
	}
	// Form: y = beta*y
	if ( beta != 1.0 ) {
		if ( beta == 0.0 ) {
			API_SUFFIX(stdlib_strided_dfill_ndarray)( N, 0.0, Y, strideY, offsetY );
		} else {
			API_SUFFIX(c_dscal_ndarray)( N, beta, Y, strideY, offsetY );
		}
	}
	if ( alpha == 0.0 ) {
		return;
	}
	// Form: y = alpha*A*x + y
	kx = offsetX;
	ky = offsetY;
	kk = offsetAP;
	if (
		( order == CblasRowMajor && uplo == CblasUpper ) ||
		( order == CblasColMajor && uplo == CblasLower )
	) {
		jx = kx;
		jy = ky;
		for ( j = 0; j < N; j++ ) {
			temp1 = alpha * X[ jx ];
			temp2 = 0.0;
			Y[ jy ] += temp1 * AP[ kk ];
			ix = jx;
			iy = jy;
			for ( k = kk + 1; k < kk + N - j; k++ ) {
				ix += strideX;
				iy += strideY;
				Y[ iy ] += temp1 * AP[ k ];
				temp2 += AP[ k ] * X[ ix ];
			}
			Y[ jy ] += alpha * temp2;
			jx += strideX;
			jy += strideY;
			kk += N - j;
		}
		return;
	}
	// ( order === 'row-major' && uplo === 'lower') || ( order === 'column-major' && uplo === 'upper' )
	jx = kx;
	jy = ky;
	for ( j = 0; j < N; j++ ) {
		temp1 = alpha * X[ jx ];
		temp2 = 0.0;
		ix = kx;
		iy = ky;
		for ( k = kk; k < kk + j; k++ ) {
			Y[ iy ] += temp1 * AP[ k ];
			temp2 += AP[ k ] * X[ ix ];
			ix += strideX;
			iy += strideY;
		}
		Y[ jy ] += ( temp1 * AP[ kk + j ] ) + ( alpha * temp2 );
		jx += strideX;
		jy += strideY;
		kk += j + 1;
	}
	return;
}
